// Aggregate reporting (DHIS2 dataValueSets) and the supervisor's question answering.
// The supervisor maps a question to a structured filter; numbers are always computed here,
// deterministically, never generated by a model.
import { classifyHb, matches } from './protocol.js';
import { verifiedHb } from './agents/check.js';

export function summarise(state, pack, now = Date.now()) {
  const a = state.history?.answers ?? {};
  const last = verifiedHb(pack, state).at(-1);
  const cls = last && Number.isFinite(Number(a.ageYears)) ? classifyHb(pack, last.gdl, Number(a.ageYears))?.cls ?? null : null;
  const tasks = Object.values(state.tasks);
  return {
    caseId: state.caseId,
    name: state.patient?.name,
    village: state.patient?.village,
    block: state.patient?.block,
    district: state.patient?.district,
    openedAt: state.openedAt,
    entry: state.entry?.role,
    status: state.status,
    hb: last?.gdl ?? null,
    hbAt: last?.at ?? null,
    hbClass: cls,
    hmb: matches(pack.rules.hmbIndicators, a).length > 0,
    urgent: state.flags.some((f) => f.severity === 'urgent'),
    falling: state.flags.some((f) => f.code === 'HB_FALLING'),
    referred: state.decision?.decision === 'refer',
    overdue: tasks.filter((t) => t.status === 'open' && t.due && Date.parse(t.due) < now).length,
    followupDone: tasks.filter((t) => t.status === 'done').length,
  };
}

/** Monthly DHIS2 dataValueSet for one org unit. */
export function toDhis2(states, pack, { period, orgUnit, now = new Date().toISOString() }) {
  const ym = period ?? now.slice(0, 7).replace('-', '');
  const inPeriod = states.filter((s) => s.openedAt?.slice(0, 7).replace('-', '') === ym);
  const rows = inPeriod.map((s) => summarise(s, pack, Date.parse(now)));
  const n = (f) => rows.filter(f).length;
  const de = pack.reporting.dhis2.indicators;
  const values = {
    screened: n((r) => r.hb != null),
    hb_mild: n((r) => r.hbClass === 'mild'),
    hb_moderate: n((r) => r.hbClass === 'moderate'),
    hb_severe: n((r) => r.hbClass === 'severe'),
    hmb_indicated: n((r) => r.hmb),
    referred: n((r) => r.referred),
    followup_completed: rows.reduce((m, r) => m + r.followupDone, 0),
    followup_overdue: rows.reduce((m, r) => m + r.overdue, 0),
  };
  return {
    dataSet: pack.reporting.dhis2.dataSet ?? undefined,
    period: ym,
    orgUnit,
    completeDate: now.slice(0, 10),
    dataValues: Object.entries(values).map(([k, v]) => ({ dataElement: de[k], value: String(v) })),
    _meta: { generatedBy: 'femos-report@0.1.0', protocol: `${pack.id}@${pack.version}`, note: pack.reporting.dhis2.note },
  };
}

const INTENTS = [
  { id: 'overdue', re: /(overdue|late|pending follow|missed|बाकी|छूटे)/i, filter: (r) => r.overdue > 0, label: 'Cases with overdue follow-up' },
  { id: 'urgent', re: /(urgent|danger|emergency|तुरंत|गंभीर लक्षण)/i, filter: (r) => r.urgent, label: 'Cases flagged for urgent review' },
  { id: 'severe', re: /(severe|गंभीर)/i, filter: (r) => r.hbClass === 'severe', label: 'Hb in WHO severe range' },
  { id: 'moderate', re: /(moderate|मध्यम)/i, filter: (r) => r.hbClass === 'moderate', label: 'Hb in WHO moderate range' },
  { id: 'anemia', re: /(an(a)?emi|एनीमिया|खून की कमी)/i, filter: (r) => r.hbClass && r.hbClass !== 'none', label: 'Hb below WHO cut-off' },
  { id: 'falling', re: /(falling|declin|drop|trend|घट)/i, filter: (r) => r.falling, label: 'Hb falling across visits' },
  { id: 'hmb', re: /(heavy|bleed|hmb|रक्तस्राव)/i, filter: (r) => r.hmb, label: 'Heavy-bleeding indicators' },
  { id: 'referred', re: /(refer|रेफ़र|रेफर)/i, filter: (r) => r.referred, label: 'Referred cases' },
  { id: 'waiting', re: /(waiting|review|queue|समीक्षा)/i, filter: (r) => r.status === 'in_review', label: 'Waiting for clinician review' },
  { id: 'self', re: /(self|own phone|खुद)/i, filter: (r) => r.entry === 'self', label: 'Cases started by the woman herself' },
];

export const INTENT_IDS = INTENTS.map((i) => i.id);
export const places = (states) => [...new Set(states.flatMap((s) => [s.patient?.village, s.patient?.block, s.patient?.district]).filter(Boolean))];

/**
 * Answer a supervisor question with a deterministic, explainable query.
 * `plan` (optional, e.g. from an LLM) = {intents, place, period}; it only selects filters.
 */
export function ask(question, states, pack, now = new Date(), plan = null) {
  const q = String(question ?? '');
  const rows = states.map((s) => summarise(s, pack, now.getTime()));
  const intents = plan ? INTENTS.filter((i) => plan.intents.includes(i.id)) : INTENTS.filter((i) => i.re.test(q));
  const filters = [];
  let out = rows;
  for (const i of intents) { out = out.filter(i.filter); filters.push(i.label); }
  const known = [...new Set(rows.flatMap((r) => [r.village, r.block, r.district]).filter(Boolean))];
  const place = plan ? plan.place : known.find((p) => q.toLowerCase().includes(p.toLowerCase()));
  if (place) { out = out.filter((r) => [r.village, r.block, r.district].includes(place)); filters.push(`in ${place}`); }
  const m = now.toISOString().slice(0, 7);
  const lm = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)).toISOString().slice(0, 7);
  const period = plan?.period ?? (/this month|इस महीने/i.test(q) ? 'this_month' : /last month|पिछले महीने/i.test(q) ? 'last_month' : 'all');
  if (period === 'this_month') { out = out.filter((r) => r.openedAt?.startsWith(m)); filters.push('opened this month'); }
  else if (period === 'last_month') { out = out.filter((r) => r.openedAt?.startsWith(lm)); filters.push('opened last month'); }
  return {
    question: q,
    understood: filters.length ? filters : ['all cases (no filter recognised)'],
    count: out.length,
    rows: out,
    planner: plan ? 'llm' : 'rules',
    method: 'deterministic filters over the case log; counts are computed, not generated',
  };
}
